--
-- Keyed by mount id. The Portuguese is in Locales/ptBR_Tips.lua, generated with this file.
local ADDON, ns = ...

ns.MountTips = {
    [401] = { year = 2021, -- Dark Phoenix
        text = "Sold by the guild vendors to a character Exalted with a guild that has {achievement:4988|Guild Glory of the Cataclysm Raider}. Joining a guild that already has it works, but the reputation with a new guild starts over. Once learnt, the mount is yours whatever guild you are in." },
    [682] = { year = 2021, -- Voidtalon of the Dark Star
        text = "The mount is in an egg on the other side of the Edge of Reality, a portal, and the egg always gives it. The portal appears rarely, at one of the marked places of six zones of Draenor, stays for some minutes and takes only the first player who clicks it. Each zone keeps its own timer: players leave one character in each zone and go round the places." },
    [802] = { year = 2018, -- Long-Forgotten Hippogryph
        text = "Five Ephemeral Crystals appear at the same time at random spots of {map:630|Azsuna}, many of them inside caves. Touching the first one starts 8 hours to touch the other four; dying loses the count. Other players are after the same crystals, and when somebody finishes they all vanish until the next round." },
    [803] = { year = 2022, -- Covenant mounts of the rares of Korthia
        text = "Four mounts, each from a rare of {map:1961|Korthia} and only for a character of its covenant: {npc:179985|Stygian Stonecrusher} (Venthyr), {npc:180032|Wild Worldcracker} (Kyrian), {npc:180013|Escaped Wilderling} (Night Fae) and {npc:180042|Fleshwing} (Necrolord). Each character has one try a day at each. What comes is not the mount: the crystal, the core and the saddle are items that start a quest, and the egg of Fleshwing hatches after 3 days. The egg comes with no message: look in the bags. Players with low renown got them." },
    [1057] = { year = 2025, -- Nazjatar Blood Serpent
        text = "1. Gather 20 {item:161344|Abyssal Fragment}: a drop of creatures of Kul Tiras and Zandalar, which can be bought at the auction house.\n2. In {map:942|Stormsong Valley}, at 73.5, 23.6, there is a cave behind a waterfall with an altar at the back: join the fragments there into the {item:161345|Abhorrent Essence of the Abyss}.\n3. Enter the mine at 46.5, 36.1 and go down to the small statue at 59.4, 54.2 on the map of the mine. Use the essence there: the {npc:140474|Adherent of the Abyss} comes.\n4. Only who summoned has a chance at the mount. In 2023 a character of level 70 killed it alone." },
    [1313] = { year = 2020, -- Rajani Warserpent
        text = "{npc:160711|Zhang Ku} sells it for 1 {item:174230|Pristine Cloud Serpent Scale}, and asks for no reputation. The scale is a rare drop of {npc:157162|Rei Lun}, a rare inside the Guo-Lai Halls, in the {map:1530|Vale of Eternal Blossoms}: from the entrance at 22.2, 24.6, straight ahead and down to the lowest floor. He is only there while the assault on the Vale is {quest:57008|Assault: The Warring Clans}, the one of the Mogu." },
    [1324] = { year = 2020, -- Elusive Quickhoof
        text = "{npc:162681|Elusive Quickhoof} is a friendly alpaca that appears at one of the marked places of {map:864|Vol'dun}, stays for about 10 minutes and takes hours to come back. Buy a {item:161128|Seaside Leafy Greens Mix} beforehand and feed it: the mount is yours. It has no rare marker on the map; it walks, and it may be lying down. Several players can feed the same one, in a raid group too." },
    [1360] = { year = 2020, -- Shimmermist Runner
        text = "It is at the end of the maze of Mistveil Tangle, in {map:1565|Ardenweald}. The way is written on the Tale of the Tangle, a scroll on a tree at 32.5, 53.1: at each crossing, go through the gate whose lamps are blue. From the entrance at 31.0, 54.5 that is left, right, left, right, straight on and left. With a wrong gate, {npc:171767|Shizgher} is not there at the end. Defeat him at 26.4, 59.0 and click the {npc:171699|Shimmermist Runner} he holds." },
    [1389] = { year = 2026, -- Battle Gargon Silessa
        text = "For a Venthyr character with the Mirror Network at tier 3. A Broken Mirror is repaired with a {item:181363|Handcrafted Mirror Repair Kit} and leads to a room with a chest, which may have the mount; each chest opens once a day. There are 3 mirrors at a time, always one of 4 fixed groups of 3, out of 12 places. The map marks the mirrors of the group that is on, which the game tells; for a character the mirrors are not for, it marks none. The group changes with the weekly reset, and sometimes in the middle of the week." },
    [1391] = { year = 2021, -- Loyal Gorger
        text = "1. Do {quest:60480|The Endmire}, of {npc:168618|Tessle the Snitch} (65.2, 63.4 in {map:1525|Revendreth}): players who skipped it never saw the item of step 2.\n2. With an {item:173939|Enticing Anima}, a drop of the creatures of the Endmire, light the braziers at 38.8, 72.0 and kill the {npc:160821|Worldedge Gorger} that comes. It may drop the {item:180583|Impressionable Gorger Spawn}; without it, try again the next day.\n3. The spawn runs away. Go down to the Endmire from Darkhaven: it appears and offers a quest. It offers one a day, and the one of day 7 gives the mount." },
    [1415] = { year = 2023, -- Arboreal Gulper
        text = "{npc:164112|Humon'gozz} is summoned. Get an {item:175247|Unusually Large Mushroom}, a rare drop of any creature of {map:1565|Ardenweald}: it lasts 20 minutes in the bags. Take it to the Damp Loam at 32.5, 30.2 and click the loam: a mushroom grows, and he comes out of it. Whoever takes part in the kill can loot, so one mushroom serves a whole group." },
    [1449] = { year = 2022, -- Covenant mounts of the rares of Korthia
        text = "Four mounts, each from a rare of {map:1961|Korthia} and only for a character of its covenant: {npc:179985|Stygian Stonecrusher} (Venthyr), {npc:180032|Wild Worldcracker} (Kyrian), {npc:180013|Escaped Wilderling} (Night Fae) and {npc:180042|Fleshwing} (Necrolord). Each character has one try a day at each. What comes is not the mount: the crystal, the core and the saddle are items that start a quest, and the egg of Fleshwing hatches after 3 days. The egg comes with no message: look in the bags. Players with low renown got them." },
    [1469] = { year = 2023, -- Magmashell
        text = "1. Get an {item:201883|Empty Magma Shell}: a rare drop of the lava snails of the west of {map:2022|The Waking Shores}, {npc:193138|Lavaslurper} among them.\n2. Take it to the {npc:199010|Empowered Snail}, at the bottom of a pool of lava at 71.0, 25.0. When it is not there, it comes back in up to 30 minutes.\n3. Click the snail, not the shell in the bags, and hold for 20 seconds. The lava kills in less than that: take a healer, a way of your class of not dying, or the toy {item:200116|Everlasting Horn of Lavaswimming}." },
    [1487] = { year = 2022, -- Covenant mounts of the rares of Korthia
        text = "Four mounts, each from a rare of {map:1961|Korthia} and only for a character of its covenant: {npc:179985|Stygian Stonecrusher} (Venthyr), {npc:180032|Wild Worldcracker} (Kyrian), {npc:180013|Escaped Wilderling} (Night Fae) and {npc:180042|Fleshwing} (Necrolord). Each character has one try a day at each. What comes is not the mount: the crystal, the core and the saddle are items that start a quest, and the egg of Fleshwing hatches after 3 days. The egg comes with no message: look in the bags. Players with low renown got them." },
    [1493] = { year = 2022, -- Covenant mounts of the rares of Korthia
        text = "Four mounts, each from a rare of {map:1961|Korthia} and only for a character of its covenant: {npc:179985|Stygian Stonecrusher} (Venthyr), {npc:180032|Wild Worldcracker} (Kyrian), {npc:180013|Escaped Wilderling} (Night Fae) and {npc:180042|Fleshwing} (Necrolord). Each character has one try a day at each. What comes is not the mount: the crystal, the core and the saddle are items that start a quest, and the egg of Fleshwing hatches after 3 days. The egg comes with no message: look in the bags. Players with low renown got them." },
    [1503] = { year = 2024, -- Hand of Nilganihmaht
        text = "The {npc:179572|Hand of Nilganihmaht} is in a cave at 25.5, 36.8 in {map:1543|The Maw}, and only in the rift phase of the zone. With the 5 rings on it, it offers the quest of the mount:\n- {item:186608|Nilganihmaht's Gold Band}: on top of a spire at 19.2, 32.3, a climb.\n- {item:186607|Nilganihmaht's Silver Ring}: in the Domination Sealed Chest at 66.0, 57.4, which takes 4 {item:186727|Seal Breaker Key}.\n- {item:186605|Nilganihmaht's Runed Band}: from {npc:179735|Torglluun}, in the rift.\n- {item:186606|Nilganihmaht's Signet Ring}: from {npc:170303|Exos, Herald of Domination}, who is summoned.\n- {item:186603|Nilganihmaht's Stone Ring}: made of 4 pieces found in Perdition Hold, with {quest:63545|Putting A Plan Together}, of the {quest:63543|Necrolord Assault}, available." },
    [1507] = { year = 2021, -- Darkmaul
        text = "{npc:180063|Darkmaul} is friendly and stands at 42.8, 32.7 in {map:1961|Korthia}. Feed it a {item:187153|Tasty Mawshroom} and ride it until the effect of 2 minutes ends: getting off before that does not count. After 10 rides the mount is in your bags; they need not be on the same day.\nThe mushroom comes, not every time, from the Invasive Mawshroom, a treasure that appears in many places of Korthia. 5 of them can be opened a day." },
    [1510] = { year = 2021, -- Dusklight Razorwing
        text = "Take 10 {item:187054|Lost Razorwing Egg} to the Razorwing Nest at 25.9, 51.4 in {map:1961|Korthia} and click the nest once for each egg: with the last one the matriarch comes down and gives the mount. The eggs drop from the devourers of Korthia, {npc:177245|Ravenous Gorger} and {npc:177582|Nimble Scavenger} among them, 2 a day at most: it takes 5 days. They can be delivered a few at a time." },
    [1545] = { year = 2023, -- Divine Kiss of Ohn'ahra
        text = "{npc:190022|Godoloto} (56.4, 73.2 in {map:2023|Ohn'ahran Plains}) offers {quest:72512|A Whispering Breeze} to who has renown 25 with the {faction:2503|Maruuk Centaur}, with the last quest of that renown done, has finished the chain of {item:192799|Lizi's Reins}, and carries in the bags, not in the bank:\n- 3 {item:201929|Stolen Breath of Ohn'ahra}: from {npc:186151|Balakar Khan}, the last boss of The Nokhud Offensive, on any difficulty.\n- 1 {item:191507|Exultant Incense} of quality 3: made by alchemists, sold at the auction house.\n- 1 {item:201323|Essence of Awakening}: {npc:196707|Quartermaster Huseng} sells it for 1 {item:194562|Occasional Sand} and 50 {currency:2003|Dragon Isles Supplies}; the sand drops from creatures of {map:2025|Thaldraszus}, {npc:187475|Eternal Sand} among them. Do not use the essence: it is spent.\nThe quest ends with {npc:194796|Ohn'ahra}, at 57.6, 31.9." },
    [1617] = { year = 2022, -- Verdant Skitterfly
        text = "Reach Renown 25 with {faction:2507|Dragonscale Expedition}. From then on it has a small chance to be inside every Expedition Scout's Pack." },
    [1656] = { year = 2023, -- Otto
        text = "A chain, most of it fishing.\n1. Get one {item:199340|Gold Coin of the Isles}: fished in the Dragon Isles, or 75 {item:199338|Copper Coin of the Isles} traded up with {npc:191608|The Great Swog}.\n2. Buy {item:202102|Immaculate Sac of Swog Treasures} from him with it. Most of the time it has {item:202042|Aquatic Shades}; when it does not, it takes another coin.\n3. Wearing the shades, dance for 5 minutes on the dance floor of the underwater bar in {map:2022|The Waking Shores}, at 19.6, 36.5.\n4. Pick up the {item:202061|Empty Fish Barrel} and fill it: 100 {item:202072|Frigid Floe Fish} (open water around Iskaara), 25 {item:202073|Calamitous Carp} (lava around the Obsidian Citadel) and 1 {item:202074|Kingfin, the Wise Whiskerfish} (water around Algeth'ar Academy).\n5. Take the barrel back to where you danced: Otto offers {quest:72738|The Way to an Otto's Heart}." },
    [1671] = { year = 2023, -- Duskwing Ohuna
        text = "{item:207026|Dreamsurge Coalescence} comes from the green orbs scattered over the zone where the Dreamsurge is active, and from the creatures killed there. {npc:210608|Celestine of the Harvest} is at the Dreamsurge symbol on the map." },
    [1672] = { year = 2022, -- Zenet Hatchling
        text = "{npc:193209|Zenet Avis} flies in circles, high over a hill, around 31.4, 63.8 in {map:2023|Ohn'ahran Plains}: fly close to it and it comes down. It drops the {item:200879|Zenet Egg}, which becomes the mount after 7 days in the bags. After a kill it takes hours to come back." },
    [1808] = { year = 2025, -- Mounts of the Dreamseed Cache
        text = "They come in the cache that grows where a seed is planted: the places marked in the {map:2200|Emerald Dream}. Click the soil to plant, or give a seed or {currency:2650|Emerald Dewdrop} to one that is growing: minutes later the cache opens for who gave.\nThe seed YOU give decides:\n- Any seed, or dewdrops alone: the Winter Night Dreamsaber, in about 1 of 200 caches.\n- {item:208047|Gigantic Dreamseed} (purple): the other six too, each in 1 of 210 caches, any of them in 1 of 35. It comes from the zone's rares and the best bag of {quest:78203|Superbloom}.\n- {item:208067|Plump Dreamseed} (blue) and {item:208066|Small Dreamseed} (green): pets and armor appearances, never those six.\nA full bar is not required; whether it raises the chance, nobody measured.\nThose six are sold too, by {npc:212797|Talisa Whisperbloom} for 1 {item:211376|Seedbloom}, at renown 18 with the {faction:2574|Dream Wardens}." },
    [1810] = { year = 2025, -- Mounts of the Dreamseed Cache
        text = "They come in the cache that grows where a seed is planted: the places marked in the {map:2200|Emerald Dream}. Click the soil to plant, or give a seed or {currency:2650|Emerald Dewdrop} to one that is growing: minutes later the cache opens for who gave.\nThe seed YOU give decides:\n- Any seed, or dewdrops alone: the Winter Night Dreamsaber, in about 1 of 200 caches.\n- {item:208047|Gigantic Dreamseed} (purple): the other six too, each in 1 of 210 caches, any of them in 1 of 35. It comes from the zone's rares and the best bag of {quest:78203|Superbloom}.\n- {item:208067|Plump Dreamseed} (blue) and {item:208066|Small Dreamseed} (green): pets and armor appearances, never those six.\nA full bar is not required; whether it raises the chance, nobody measured.\nThose six are sold too, by {npc:212797|Talisa Whisperbloom} for 1 {item:211376|Seedbloom}, at renown 18 with the {faction:2574|Dream Wardens}." },
    [1815] = { year = 2025, -- Mounts of the Dreamseed Cache
        text = "They come in the cache that grows where a seed is planted: the places marked in the {map:2200|Emerald Dream}. Click the soil to plant, or give a seed or {currency:2650|Emerald Dewdrop} to one that is growing: minutes later the cache opens for who gave.\nThe seed YOU give decides:\n- Any seed, or dewdrops alone: the Winter Night Dreamsaber, in about 1 of 200 caches.\n- {item:208047|Gigantic Dreamseed} (purple): the other six too, each in 1 of 210 caches, any of them in 1 of 35. It comes from the zone's rares and the best bag of {quest:78203|Superbloom}.\n- {item:208067|Plump Dreamseed} (blue) and {item:208066|Small Dreamseed} (green): pets and armor appearances, never those six.\nA full bar is not required; whether it raises the chance, nobody measured.\nThose six are sold too, by {npc:212797|Talisa Whisperbloom} for 1 {item:211376|Seedbloom}, at renown 18 with the {faction:2574|Dream Wardens}." },
